"""Auth endpoints: JWT login, refresh and current user (NFR-04).

Uses simplejwt's token obtain/refresh views so the schema is generated by
DRF spectacular, plus a tiny /me endpoint the frontend can call after login.
"""
from rest_framework import serializers
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework_simplejwt import serializers as jwt_serializers
from rest_framework_simplejwt import views as jwt_views


class TokenObtainPairResponseSerializer(serializers.Serializer):
    access = serializers.CharField()
    refresh = serializers.CharField()


class TokenRefreshResponseSerializer(serializers.Serializer):
    access = serializers.CharField()
    refresh = serializers.CharField(required=False)


class TokenObtainPairView(jwt_views.TokenObtainPairView):
    """POST {username, password} -> {access, refresh}."""

    default_response_serializer_class = TokenObtainPairResponseSerializer

    @property
    def serializer_class(self):
        return self.default_response_serializer_class


class TokenRefreshView(jwt_views.TokenRefreshView):
    """POST {refresh} -> new {access} (and refresh, if ROTATE_REFRESH_TOKENS)."""

    default_response_serializer_class = TokenRefreshResponseSerializer

    @property
    def serializer_class(self):
        return self.default_response_serializer_class


class MeView(APIView):
    """GET current authenticated user, for the frontend after login."""

    permission_classes = [IsAuthenticated]

    class OutputSerializer(serializers.Serializer):
        id = serializers.IntegerField()
        username = serializers.CharField()
        email = serializers.EmailField()

    def get(self, request):
        user = request.user
        out = self.OutputSerializer(
            {"id": user.id, "username": user.username, "email": user.email or ""}
        )
        return Response(out.data)

