"""OpenAPI specification parsing and validation (FR-01, FR-02).

Turns raw YAML/JSON text into:
  - `info` (title, version) extracted for registry metadata
  - a $ref-expanded `contract` stored on SpecVersion, so comparisons work
    on the real contract rather than file layout

Only local references (`#/components/...`) are supported, which is what
the kit's specs use.
"""
import json

import yaml

MAX_SPEC_BYTES = 2 * 1024 * 1024  # 2 MB guard against accidental huge uploads


class SpecParseError(Exception):
    """Raised when an uploaded spec cannot be parsed or is not valid OpenAPI."""

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _load_spec(text):
    """Parse raw text as YAML (which also covers JSON) into a dict."""
    if len(text) > MAX_SPEC_BYTES:
        raise SpecParseError("spec is too large (max 2 MB)")
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise SpecParseError(f"invalid YAML/JSON: {e}") from e
    if not isinstance(data, dict):
        raise SpecParseError("spec must be a YAML/JSON mapping (object)")
    return data


def _check_openapi(data):
    version = str(data.get("openapi", ""))
    if not version:
        raise SpecParseError("missing openapi version field")
    if not version.startswith("3.0."):
        raise SpecParseError(f"only OpenAPI 3.0.x is supported, got '{version}'")
    info = data.get("info")
    if not isinstance(info, dict) or not info.get("version"):
        raise SpecParseError("missing info.version")


def _expand_refs(node, root, depth=0):
    """Recursively replace local $refs with the pointed-to schema object.

    Mutates and returns `node`. Bounded depth guards against circular refs.
    """
    if depth > 32:
        raise SpecParseError("spec has too-deeply nested $refs (possible circular reference)")
    if isinstance(node, dict):
        ref = node.get("$ref")
        if isinstance(ref, str) and ref.startswith("#/"):
            target = root
            for part in ref[2:].split("/"):
                part = part.replace("~1", "/").replace("~0", "~")
                if not isinstance(target, dict) or part not in target:
                    raise SpecParseError(f"broken $ref: '{ref}'")
                target = target[part]
            merged = _expand_refs(target, root, depth + 1)
            # keep sibling keys (e.g. description next to $ref), $ref resolved wins
            merged = {**merged, **{k: v for k, v in node.items() if k != "$ref"}}
            return merged
        return {k: _expand_refs(v, root, depth + 1) for k, v in node.items()}
    if isinstance(node, list):
        return [_expand_refs(v, root, depth + 1) for v in node]
    return node


def parse_spec(text):
    """Parse raw spec text -> dict with openapi_version, info, contract.

    Raises SpecParseError on invalid input. `contract` is the fully
    $ref-expanded deep copy safe to store as JSON.
    """
    data = _load_spec(text)
    _check_openapi(data)
    info = data.get("info", {})
    contract = _expand_refs(data, data)
    # round-trip through JSON to guarantee JSONField-serializable content
    contract = json.loads(json.dumps(contract))
    return {
        "openapi_version": str(data["openapi"]),
        "title": info.get("title", ""),
        "version": str(info["version"]),
        "contract": contract,
    }

"""Service registry and spec upload endpoints (FR-01, FR-02).

Function-based views with api_view + explicit extend_schema on every
operation, so Swagger UI renders the exact fields from the serializers.
"""
from django.shortcuts import get_object_or_404
from drf_spectacular.utils import OpenApiResponse, extend_schema
from rest_framework import status
from rest_framework.decorators import api_view, permission_classes
from rest_framework.pagination import PageNumberPagination
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response

from base.models import Service, SpecStatus
from base.serializers.service_serializers import (
    ServiceCreateSerializer,
    ServiceOutSerializer,
    SpecDetailOutSerializer,
    SpecOutSerializer,
    SpecUploadSerializer,
)
from base.services.spec_parser import SpecParseError, parse_spec


def _published_version(service: Service):
    published = service.spec_versions.filter(status=SpecStatus.PUBLISHED).first()
    return published.version if published else None


def _service_out(service: Service) -> dict:
    data = ServiceOutSerializer(
        {
            "id": service.id,
            "name": service.name,
            "owner_team": service.owner_team,
            "description": service.description,
            "published_version": _published_version(service),
            "created_at": service.created_at,
        }
    )
    return data.data


@extend_schema(
    request=ServiceCreateSerializer,
    responses={201: ServiceOutSerializer},
    summary="Register a service",
    operation_id="services_create",
)
@api_view(["POST"])
@permission_classes([IsAuthenticated])
def service_create(request):
    serializer = ServiceCreateSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    data = serializer.validated_data
    if Service.objects.filter(name__iexact=data["name"]).exists():
        return Response({"name": ["service name already registered"]}, status=status.HTTP_400_BAD_REQUEST)
    service = Service.objects.create(**data)
    return Response(_service_out(service), status=status.HTTP_201_CREATED)


@extend_schema(
    responses={200: ServiceOutSerializer(many=True)},
    summary="List registered services",
    operation_id="services_list",
)
@api_view(["GET"])
@permission_classes([IsAuthenticated])
def service_list(request):
    paginator = PageNumberPagination(page_size=50)
    services = paginator.paginate_queryset(Service.objects.all(), request, view=None)
    return paginator.get_paginated_response([_service_out(s) for s in services])


@extend_schema(
    responses={200: ServiceOutSerializer},
    summary="Service detail",
    operation_id="services_retrieve",
)
@api_view(["GET"])
@permission_classes([IsAuthenticated])
def service_detail(request, service_id):
    service = get_object_or_404(Service, id=service_id)
    return Response(_service_out(service))


@extend_schema(
    request=SpecUploadSerializer,
    responses={
        201: SpecOutSerializer,
        400: OpenApiResponse(description="Invalid YAML/JSON, not OpenAPI 3.0.x, or missing info.version"),
    },
    summary="Upload a new spec version for this service (YAML/JSON text or file)",
    operation_id="specs_upload",
)
@api_view(["POST"])
@permission_classes([IsAuthenticated])
def spec_upload(request, service_id):
    service = get_object_or_404(Service, id=service_id)

    body = {}
    if request.FILES.get("file"):
        body["file"] = request.FILES["file"]
    if isinstance(request.data, dict) and request.data.get("spec_text"):
        body["spec_text"] = request.data["spec_text"]
    serializer = SpecUploadSerializer(data=body)
    serializer.is_valid(raise_exception=True)

    if serializer.validated_data.get("file"):
        raw = serializer.validated_data["file"].read()
        text = raw.decode("utf-8", "replace") if isinstance(raw, bytes) else str(raw)
    else:
        text = serializer.validated_data["spec_text"]

    try:
        parsed = parse_spec(text)
    except SpecParseError as e:
        return Response({"spec": [e.message]}, status=status.HTTP_400_BAD_REQUEST)

    spec_version = SpecVersion.objects.create(
        service=service,
        version=parsed["version"],
        spec=text,
        contract={"openapi_version": parsed["openapi_version"], "title": parsed["title"], **parsed["contract"]},
    )
    return Response(SpecOutSerializer().to_representation(spec_version), status=status.HTTP_201_CREATED)


@extend_schema(
    responses={200: SpecOutSerializer(many=True)},
    summary="List this service's spec versions",
    operation_id="specs_list",
)
@api_view(["GET"])
@permission_classes([IsAuthenticated])
def spec_list(request, service_id):
    service = get_object_or_404(Service, id=service_id)
    paginator = PageNumberPagination(page_size=50)
    specs = paginator.paginate_queryset(
        service.spec_versions.order_by("created_at"), request, view=None
    )
    return paginator.get_paginated_response([SpecOutSerializer().to_representation(s) for s in specs])


@extend_schema(
    responses={200: SpecDetailOutSerializer},
    summary="Spec version detail (includes raw spec and expanded contract)",
    operation_id="specs_retrieve",
)
@api_view(["GET"])
@permission_classes([IsAuthenticated])
def spec_detail(request, service_id, spec_id):
    spec = get_object_or_404(SpecVersion, id=spec_id, service_id=service_id)
    return Response(SpecDetailOutSerializer().to_representation(spec))

