"""Serializers for the Consumer registry API (FR-05).

The request shape intentionally matches the starter kit's consumer files
({consumer, team, uses: [{provider, method, path, sends, reads}]}) so a
kit file converts to a request body by YAML->JSON alone.
"""
from rest_framework import serializers

HTTP_METHODS = {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS", "TRACE"}


class ConsumerUseInSerializer(serializers.Serializer):
    provider = serializers.CharField(help_text="Provider service name, e.g. quote-api")
    method = serializers.CharField(help_text="HTTP method, e.g. POST")
    path = serializers.CharField(help_text="Path template, e.g. /quotes/{id}")
    sends = serializers.ListField(
        child=serializers.CharField(), required=False, default=list,
        help_text="Request fields/parameters this consumer sends",
    )
    reads = serializers.ListField(
        child=serializers.CharField(), required=False, default=list,
        help_text="Response fields this consumer reads",
    )


class ConsumerInSerializer(serializers.Serializer):
    consumer = serializers.CharField(required=False, help_text="Consumer service name, e.g. mobile-app")
    name = serializers.CharField(required=False, help_text="Alias of 'consumer' (either works)")
    team = serializers.CharField(help_text="Owning team, e.g. Mobile")
    uses = ConsumerUseInSerializer(many=True, required=False)

    def validate(self, attrs):
        if not attrs.get("consumer") and not attrs.get("name"):
            raise serializers.ValidationError("provide 'consumer' (or alias 'name')")
        return attrs

    def get_name(self, validated):
        return validated.get("consumer") or validated.get("name")


class ConsumerOutSerializer(serializers.Serializer):
    id = serializers.IntegerField()
    name = serializers.CharField()
    team = serializers.CharField()
    uses = serializers.ListField()


def consumer_out(consumer) -> dict:
    uses = []
    for use in consumer.uses.all():
        deps = list(use.field_dependencies.order_by("field_path"))
        uses.append(
            {
                "id": use.id,
                "provider": use.provider_service.name,
                "provider_id": use.provider_service_id,
                "method": use.method,
                "path": use.path,
                "sends": [d.field_path for d in deps if d.direction == "sends"],
                "reads": [d.field_path for d in deps if d.direction == "reads"],
            }
        )
    return {
        "id": consumer.id,
        "name": consumer.name,
        "team": consumer.team,
        "uses": uses,
    }

"""Consumer registry endpoints (FR-05).

Registering a consumer with an existing name replaces its declared uses
(idempotent re-registration — re-posting a kit consumer file refreshes it).
"""
from django.db import transaction
from django.shortcuts import get_object_or_404
from drf_spectacular.utils import OpenApiResponse, extend_schema, extend_schema_view
from rest_framework import status
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response

from base.models import APIConsumer, ConsumerUse, DependencyDirection, FieldDependency, Service
from base.serializers.consumer_serializers import (
    ConsumerInSerializer,
    HTTP_METHODS,
    consumer_out,
)
from base.views.sns_views import ListPagination


def _create_uses(consumer, uses_data):
    """Create ConsumerUse + FieldDependency rows (dedup, validated data)."""
    for use_data in uses_data:
        provider = Service.objects.get(name__iexact=use_data["provider"])
        use = ConsumerUse.objects.create(
            consumer=consumer,
            provider_service=provider,
            method=use_data["method"].upper(),
            path=use_data["path"],
        )
        deps = [
            FieldDependency(use=use, direction=direction, field_path=field_path)
            for direction, key in (
                (DependencyDirection.SENDS, "sends"),
                (DependencyDirection.READS, "reads"),
            )
            for field_path in dict.fromkeys(use_data[key])  # dedupe, keep order
        ]
        FieldDependency.objects.bulk_create(deps)


@extend_schema_view(
    post=extend_schema(
        request=ConsumerInSerializer,
        responses={
            201: ConsumerOutSerializer,
            400: OpenApiResponse(description="Unknown provider service or invalid method/path"),
        },
        summary="Register a consumer with its declared endpoint uses and field dependencies",
        operation_id="consumers_create",
    ),
    get=extend_schema(
        responses={200: ConsumerOutSerializer(many=True)},
        summary="List consumers with their declared uses",
        operation_id="consumers_list",
    ),
)
@api_view(["GET", "POST"])
@permission_classes([IsAuthenticated])
def consumers(request):
    if request.method == "GET":
        paginator = ListPagination()
        page = paginator.paginate_queryset(
            APIConsumer.objects.prefetch_related("uses__provider_service", "uses__field_dependencies"),
            request,
            view=None,
        )
        return paginator.get_paginated_response([consumer_out(c) for c in page])

    serializer = ConsumerInSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    validated = serializer.validated_data
    name = serializer.get_name(validated)
    uses_data = validated.get("uses") or []

    # validate providers and methods up-front for an all-or-nothing result
    errors = []
    for i, use_data in enumerate(uses_data):
        if not Service.objects.filter(name__iexact=use_data["provider"]).exists():
            errors.append(f"uses[{i}].provider: unknown service '{use_data['provider']}'")
        if use_data["method"].upper() not in HTTP_METHODS:
            errors.append(f"uses[{i}].method: invalid HTTP method '{use_data['method']}'")
        if not use_data["path"].startswith("/"):
            errors.append(f"uses[{i}].path: must start with '/'")
    if errors:
        return Response({"uses": errors}, status=status.HTTP_400_BAD_REQUEST)

    with transaction.atomic():
        consumer, _ = APIConsumer.objects.get_or_create(name__iexact=name, defaults={"name": name, "team": validated["team"]})
        consumer.team = validated["team"]
        consumer.save(update_fields=["team"])
        consumer.uses.all().delete()  # idempotent re-registration
        _create_uses(consumer, uses_data)

    consumer.refresh_from_db()
    return Response(consumer_out(consumer), status=status.HTTP_201_CREATED)


@extend_schema(
    responses={200: ConsumerOutSerializer},
    summary="Consumer detail",
    operation_id="consumers_retrieve",
)
@api_view(["GET"])
@permission_classes([IsAuthenticated])
def consumer_detail(request, consumer_id):
    consumer = get_object_or_404(
        APIConsumer.objects.prefetch_related("uses__provider_service", "uses__field_dependencies"),
        id=consumer_id,
    )
    return Response(consumer_out(consumer))

"""Publishing workflow endpoints (FR-07, FR-08).

Gate rule (MVP): attempting to publish a spec version compares it against
the currently published version (fallback: latest earlier version; none ->
first version, publishes immediately). If any breaking change affects a
registered consumer, the attempt is BLOCKED and an ImpactReport is stored;
otherwise it is APPROVED and the version becomes the service's published
one. Blocked/rejected attempts never touch the published version (NFR-02).
Every attempt and decision sends a webhook notification (FR-10).
"""
from django.db import transaction
from django.shortcuts import get_object_or_404
from django.utils import timezone
from drf_spectacular.utils import OpenApiResponse, extend_schema
from rest_framework import status
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response

from base.models import (
    APIChange,
    APIComparison,
    AttemptStatus,
    Notification,
    SpecStatus,
    SpecVersion,
)
from base.serializers.attempt_serializers import (
    AttemptCreateInSerializer,
    AttemptDecisionInSerializer,
    attempt_out,
)
from base.services.differ import compare_contracts
from base.services.impact import create_impact_report
from base.services.notify import send_webhook
from base.views.sns_views import ListPagination

RECEIVER = "http://localhost:9900/contract-guard"


def _notify(attempt, event, blocked_reasons, affected_consumers):
    payload = {
        "event": event,
        "service": attempt.service.name,
        "version": attempt.spec_version.version,
        "attempt_id": attempt.id,
        "status": attempt.status,
        "blocked_reasons": blocked_reasons,
        "affected_consumers": affected_consumers,
    }
    delivered, response_status = send_webhook(payload)
    Notification.objects.create(
        attempt=attempt, payload=payload, receiver_url=RECEIVER,
        delivered=delivered, response_status=response_status,
    )


def _base_version_for(spec: SpecVersion):
    """Currently published version, else the latest earlier upload."""
    published = spec.service.spec_versions.filter(status=SpecStatus.PUBLISHED).first()
    if published and published.pk != spec.pk:
        return published
    return spec.service.spec_versions.filter(pk__lt=spec.pk).order_by("-pk").first()


def _get_or_create_comparison(base: SpecVersion, target: SpecVersion) -> APIComparison:
    comparison = (
        APIComparison.objects.filter(target_version=target).order_by("-created_at").first()
    )
    if comparison and comparison.base_version_id == base.pk:
        return comparison
    comparison = APIComparison.objects.create(base_version=base, target_version=target)
    detected = compare_contracts(base.contract or {}, target.contract or {})
    APIChange.objects.bulk_create(
        [
            APIChange(
                comparison=comparison,
                path=c["path"],
                method=c["method"],
                field_path=c["field_path"],
                side=c["side"],
                change_type=c["change_type"],
                severity=c["severity"],
                breaking=c["breaking"],
                explanation=c["explanation"],
                old_value=c["old_value"],
                new_value=c["new_value"],
            )
            for c in detected
        ]
    )
    return comparison


def _publish(spec: SpecVersion):
    """Make `spec` the service's single published version (NFR-02)."""
    spec.service.spec_versions.exclude(pk=spec.pk).filter(status=SpecStatus.PUBLISHED).update(
        status=SpecStatus.DRAFT
    )
    spec.status = SpecStatus.PUBLISHED
    spec.save(update_fields=["status"])


@extend_schema(
    request=AttemptCreateInSerializer,
    responses={
        201: OpenApiResponse(description="Attempt created; status is 'approved' or 'blocked'"),
        400: OpenApiResponse(description="Version already published"),
    },
    summary="Attempt to publish a spec version (auto-approved unless consumers are affected)",
    operation_id="attempts_create",
)
@api_view(["POST"])
@permission_classes([IsAuthenticated])
def publishing_attempts(request):
    if request.method == "GET":
        paginator = ListPagination()
        page = paginator.paginate_queryset(
            __import__("base.models", fromlist=["PublishingAttempt"]).PublishingAttempt.objects.select_related(
                "service", "spec_version", "comparison", "impact_report"
            ).order_by("-created_at"),
            request,
            view=None,
        )
        return paginator.get_paginated_response([attempt_out(a) for a in page])

    serializer = AttemptCreateInSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    spec = get_object_or_404(
        SpecVersion.objects.select_related("service"), id=serializer.validated_data["spec_version_id"]
    )
    if spec.status == SpecStatus.PUBLISHED:
        return Response(
            {"detail": f"version {spec.version} is already published"},
            status=status.HTTP_400_BAD_REQUEST,
        )

    base = _base_version_for(spec)
    comparison = report = None
    affected, reasons = [], []

    if base is not None:
        comparison = _get_or_create_comparison(base, spec)
        from base.models import ImpactReport as _IR  # noqa: F401  (import used below)
        report, hits = create_impact_report(comparison)
        affected = sorted({h[1].name for h in hits})
        reasons = _reasons(report)

    with transaction.atomic():
        if not affected:
            _publish(spec)
            attempt_status = AttemptStatus.APPROVED
        else:
            spec.status = SpecStatus.BLOCKED
            spec.save(update_fields=["status"])
            attempt_status = AttemptStatus.BLOCKED

        from base.models import PublishingAttempt

        attempt = PublishingAttempt.objects.create(
            service=spec.service,
            spec_version=spec,
            status=attempt_status,
            comparison=comparison,
            impact_report=report,
        )

    _notify(
        attempt,
        "publish.approved" if attempt_status == AttemptStatus.APPROVED else "publish.blocked",
        reasons,
        affected,
    )
    return Response(attempt_out(attempt), status=status.HTTP_201_CREATED)


def _reasons(report):
    if report is None:
        return []
    return list(report.items.values_list("reason", flat=True))


@extend_schema(
    request=AttemptDecisionInSerializer,
    responses={200: OpenApiResponse(description="Attempt approved; version is now published")},
    summary="Approve a blocked attempt (publishes the version)",
    operation_id="attempts_approve",
)
@api_view(["POST"])
@permission_classes([IsAuthenticated])
def attempt_approve(request, attempt_id):
    from base.models import PublishingAttempt

    attempt = get_object_or_404(
        PublishingAttempt.objects.select_related("service", "spec_version"), id=attempt_id
    )
    if attempt.status != AttemptStatus.BLOCKED:
        return Response(
            {"detail": f"only blocked attempts can be approved (this one is '{attempt.status}')"},
            status=status.HTTP_400_BAD_REQUEST,
        )
    serializer = AttemptDecisionInSerializer(data=request.data or {})
    serializer.is_valid(raise_exception=True)

    with transaction.atomic():
        _publish(attempt.spec_version)
        attempt.status = AttemptStatus.APPROVED
        attempt.decided_by = request.user
        attempt.decided_at = timezone.now()
        attempt.comment = serializer.validated_data.get("comment", "")
        attempt.save()

    _notify(attempt, "publish.approved", _reasons(attempt.impact_report), _affected(attempt))
    return Response(attempt_out(attempt))


@extend_schema(
    request=AttemptDecisionInSerializer,
    responses={200: OpenApiResponse(description="Attempt rejected; published version unchanged")},
    summary="Reject a blocked attempt (version stays unpublished)",
    operation_id="attempts_reject",
)
@api_view(["POST"])
@permission_classes([IsAuthenticated])
def attempt_reject(request, attempt_id):
    from base.models import PublishingAttempt

    attempt = get_object_or_404(
        PublishingAttempt.objects.select_related("service", "spec_version"), id=attempt_id
    )
    if attempt.status != AttemptStatus.BLOCKED:
        return Response(
            {"detail": f"only blocked attempts can be rejected (this one is '{attempt.status}')"},
            status=status.HTTP_400_BAD_REQUEST,
        )
    serializer = AttemptDecisionInSerializer(data=request.data or {})
    serializer.is_valid(raise_exception=True)

    attempt.status = AttemptStatus.REJECTED
    attempt.decided_by = request.user
    attempt.decided_at = timezone.now()
    attempt.comment = serializer.validated_data.get("comment", "")
    attempt.save()
    attempt.spec_version.status = SpecStatus.DRAFT
    attempt.spec_version.save(update_fields=["status"])

    _notify(attempt, "publish.rejected", _reasons(attempt.impact_report), _affected(attempt))
    return Response(attempt_out(attempt))


def _affected(attempt):
    if attempt.impact_report is None:
        return []
    return sorted({i.consumer.name for i in attempt.impact_report.items.select_related("consumer")})

