import axios from 'axios'

/**
 * Single axios instance for the whole app.
 * The Vite dev server proxies /api to Django (see vite.config.js), so the
 * baseURL is just /api — no CORS or host juggling in code.
 */
const api = axios.create({
  baseURL: '/api',
  headers: { 'Content-Type': 'application/json' },
})

// --- JWT request interceptor: attach the access token when present -------
const TOKEN_KEY = 'cg_access_token'

export const getToken = () => localStorage.getItem(TOKEN_KEY)
export const setToken = (token) => {
  if (token) localStorage.setItem(TOKEN_KEY, token)
  else localStorage.removeItem(TOKEN_KEY)
}

api.interceptors.request.use((config) => {
  const token = getToken()
  if (token) config.headers.Authorization = `Bearer ${token}`
  return config
})

// --- Response interceptor: on 401, drop the stale token and go to login --
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      setToken(null)
      // avoid redirect loops for the login page itself
      if (!window.location.hash.includes('/login')) {
        window.location.assign('/login')
      }
    }
    return Promise.reject(error)
  },
)

export default api

/**
 * Auth context: register/login/logout + current user.
 * The JWT access token lives in localStorage and is attached to every
 * request by the axios interceptor in api/client.js.
 */
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import api, { getToken, setToken } from '../api/client'

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [initializing, setInitializing] = useState(true)

  // restore the session on first load if a token exists
  useEffect(() => {
    if (!getToken()) {
      setInitializing(false)
      return
    }
    api
      .get('/auth/me/')
      .then((res) => setUser(res.data))
      .catch(() => setToken(null))
      .finally(() => setInitializing(false))
  }, [])

  const register = useCallback(async (username, password, email = '') => {
    const { data } = await api.post('/auth/register/', { username, password, email })
    setToken(data.access)
    const me = await api.get('/auth/me/')
    setUser(me.data)
    return me.data
  }, [])

  const login = useCallback(async (username, password) => {
    const { data } = await api.post('/auth/login/', { username, password })
    setToken(data.access)
    const me = await api.get('/auth/me/')
    setUser(me.data)
    return me.data
  }, [])

  const logout = useCallback(() => {
    setToken(null)
    setUser(null)
  }, [])

  const value = useMemo(
    () => ({ user, initializing, register, login, logout }),
    [user, initializing, register, login, logout],
  )
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used inside <AuthProvider>')
  return ctx
}

