input.content:
import { Chip } from '@mui/material'

const COLORS = {
  blocker: 'error',
  major: 'warning',
  minor: 'info',
  info: 'default',
  approved: 'success',
  blocked: 'error',
  rejected: 'default',
  published: 'success',
  draft: 'default',
}

export default function SeverityChip({ value, label }) {
  return (
    <Chip
      size="small"
      color={COLORS[value] || 'default'}
      label={label ?? value}
      variant={COLORS[value] ? 'filled' : 'outlined'}
    />
  )
}

/** Extract a human-readable message from an axios/DRF error. */
export default function errorMessage(err, fallback = 'Something went wrong') {
  const data = err?.response?.data
  if (!data) return err?.message || fallback
  if (typeof data === 'string') return data
  if (data.detail) return data.detail
  if (typeof data === 'object') {
    return Object.entries(data)
      .map(([key, value]) => {
        const text = Array.isArray(value) ? value.join(', ') : String(value)
        return key === 'detail' ? text : `${key}: ${text}`
      })
      .join(' | ')
  }
  return fallback
}

import { useCallback, useEffect, useState } from 'react'
import { Link as RouterLink, useNavigate } from 'react-router-dom'
import {
  Alert,
  Button,
  Card,
  CardActionArea,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material'
import AddIcon from '@mui/icons-material/Add'
import api from '../api/client'
import errorMessage from '../api/errorMessage'

export default function ServicesPage() {
  const [services, setServices] = useState([])
  const [loading, setLoading] = useState(true)
  const [pageError, setPageError] = useState(null)
  const [open, setOpen] = useState(false)
  const navigate = useNavigate()

  const load = useCallback(() => {
    setLoading(true)
    api
      .get('/services/')
      .then((res) => setServices(res.data.results ?? res.data))
      .catch((err) => setPageError(errorMessage(err)))
      .finally(() => setLoading(false))
  }, [])

  useEffect(load, [load])

  return (
    <Stack spacing={3}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="h4">Services</Typography>
        <Button variant="contained" startIcon={<AddIcon />} onClick={() => setOpen(true)}>
          Register service
        </Button>
      </Stack>

      {pageError && <Alert severity="error">{pageError}</Alert>}
      {loading && <Typography color="text.secondary">Loading…</Typography>}
      {!loading && services.length === 0 && (
        <Typography color="text.secondary">
          No services registered yet — click “Register service” to add the first API provider.
        </Typography>
      )}

      <Grid container spacing={2}>
        {services.map((svc) => (
          <Grid key={svc.id} size={{ xs: 12, sm: 6, md: 4 }}>
            <Card>
              <CardActionArea component={RouterLink} to={`/services/${svc.id}`}>
                <CardContent>
                  <Stack direction="row" spacing={1} alignItems="center" justifyContent="space-between">
                    <Typography variant="h6" sx={{ fontWeight: 600 }}>
                      {svc.name}
                    </Typography>
                    {svc.published_version ? (
                      <Chip size="small" color="success" label={`v${svc.published_version} published`} />
                    ) : (
                      <Chip size="small" label="nothing published" variant="outlined" />
                    )}
                  </Stack>
                  <Typography variant="body2" color="text.secondary">
                    Owner: {svc.owner_team}
                  </Typography>
                  {svc.description && (
                    <Typography variant="body2" sx={{ mt: 1 }}>
                      {svc.description}
                    </Typography>
                  )}
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))}
      </Grid>

      <RegisterServiceDialog
        open={open}
        onClose={() => setOpen(false)}
        onCreated={(svc) => {
          setOpen(false)
          navigate(`/services/${svc.id}`)
        }}
        onReload={load}
      />
    </Stack>
  )
}

function RegisterServiceDialog({ open, onClose, onCreated }) {
  const [form, setForm] = useState({ name: '', owner_team: '', description: '' })
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  const change = (field) => (e) => setForm((f) => ({ ...f, [field]: e.target.value }))

  const submit = async (e) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)
    try {
      const { data } = await api.post('/services/', form)
      onCreated(data)
    } catch (err) {
      setError(errorMessage(err, 'Could not register the service'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <form onSubmit={submit}>
        <DialogTitle>Register a service</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}
            <TextField
              label="Service name"
              placeholder="quote-api"
              value={form.name}
              onChange={change('name')}
              required
              autoFocus
            />
            <TextField
              label="Owner team"
              placeholder="Quotes team"
              value={form.owner_team}
              onChange={change('owner_team')}
              required
            />
            <TextField
              label="Description (optional)"
              multiline
              rows={2}
              value={form.description}
              onChange={change('description')}
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button type="submit" variant="contained" disabled={submitting}>
            {submitting ? 'Registering…' : 'Register'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Link as RouterLink, useNavigate, useParams } from 'react-router-dom'
import {
  Alert,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  LinearProgress,
  MenuItem,
  Stack,
  Tab,
  Tabs,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material'
import ArrowBackIcon from '@mui/icons-material/ArrowBack'
import CompareArrowsIcon from '@mui/icons-material/CompareArrows'
import PublishIcon from '@mui/icons-material/Publish'
import UploadFileIcon from '@mui/icons-material/UploadFile'
import VisibilityIcon from '@mui/icons-material/Visibility'
import api from '../api/client'
import errorMessage from '../api/errorMessage'
import SeverityChip from '../components/SeverityChip'

export default function ServiceDetailPage() {
  const { serviceId } = useParams()
  const navigate = useNavigate()

  const [service, setService] = useState(null)
  const [specs, setSpecs] = useState([])
  const [loading, setLoading] = useState(true)
  const [pageError, setPageError] = useState(null)

  const [uploadOpen, setUploadOpen] = useState(false)
  const [compareOpen, setCompareOpen] = useState(false)
  const [viewingSpec, setViewingSpec] = useState(null)
  const [publishResult, setPublishResult] = useState(null)

  const load = useCallback(() => {
    setLoading(true)
    Promise.all([api.get(`/services/${serviceId}/`), api.get(`/services/${serviceId}/specs/`)])
      .then(([svcRes, specRes]) => {
        setService(svcRes.data)
        setSpecs(specRes.data.results ?? specRes.data)
        setPageError(null)
      })
      .catch((err) => setPageError(errorMessage(err)))
      .finally(() => setLoading(false))
  }, [serviceId])

  useEffect(load, [load])

  const attemptPublish = async (specId) => {
    try {
      const { data } = await api.post('/publishing-attempts/', { spec_version_id: specId })
      setPublishResult(data)
      load()
    } catch (err) {
      setPublishResult({ _error: errorMessage(err) })
    }
  }

  if (loading) return <LinearProgress />
  if (pageError) return <Alert severity="error">{pageError}</Alert>
  if (!service) return null

  return (
    <Stack spacing={3}>
      <Button component={RouterLink} to="/services" startIcon={<ArrowBackIcon />} sx={{ alignSelf: 'flex-start' }}>
        All services
      </Button>

      <Stack direction="row" alignItems="center" justifyContent="space-between" flexWrap="wrap">
        <Stack>
          <Typography variant="h4">{service.name}</Typography>
          <Typography variant="body2" color="text.secondary">
            Owner: {service.owner_team}
            {service.description ? ` · ${service.description}` : ''}
          </Typography>
          <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
            {service.published_version ? (
              <Chip color="success" size="small" label={`published: v${service.published_version}`} />
            ) : (
              <Chip size="small" variant="outlined" label="nothing published yet" />
            )}
          </Stack>
        </Stack>
        <Stack direction="row" spacing={1}>
          <Button variant="contained" startIcon={<UploadFileIcon />} onClick={() => setUploadOpen(true)}>
            Upload spec
          </Button>
          <Button variant="outlined" startIcon={<CompareArrowsIcon />} onClick={() => setCompareOpen(true)}>
            Compare versions
          </Button>
        </Stack>
      </Stack>

      {specs.length === 0 ? (
        <Typography color="text.secondary">
          No spec versions uploaded yet — click “Upload spec” to add v1.
        </Typography>
      ) : (
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Version</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Title</TableCell>
                <TableCell>Uploaded</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {specs.map((spec) => (
                <TableRow key={spec.id}>
                  <TableCell sx={{ fontWeight: 600 }}>v{spec.version}</TableCell>
                  <TableCell>
                    <SeverityChip value={spec.status} />
                  </TableCell>
                  <TableCell>{spec.title || '—'}</TableCell>
                  <TableCell>{new Date(spec.created_at).toLocaleString()}</TableCell>
                  <TableCell align="right">
                    <Stack direction="row" spacing={1} justifyContent="flex-end">
                      <Button size="small" startIcon={<VisibilityIcon />} onClick={() => setViewingSpec(spec.id)}>
                        View
                      </Button>
                      <Button size="small" startIcon={<PublishIcon />} onClick={() => attemptPublish(spec.id)}>
                        Publish
                      </Button>
                    </Stack>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <UploadSpecDialog open={uploadOpen} onClose={() => setUploadOpen(false)} serviceId={serviceId} onUploaded={load} />
      <CompareDialog
        open={compareOpen}
        onClose={() => setCompareOpen(false)}
        specs={specs}
        onCompared={(comparison) => navigate(`/comparisons/${comparison.id}`)}
      />
      <SpecViewDialog serviceId={serviceId} specId={viewingSpec} onClose={() => setViewingSpec(null)} />
      <PublishResultDialog result={publishResult} onClose={() => setPublishResult(null)} />
    </Stack>
  )
}

function UploadSpecDialog({ open, onClose, serviceId, onUploaded }) {
  const [mode, setMode] = useState('paste')
  const [specText, setSpecText] = useState('')
  const [file, setFile] = useState(null)
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  const reset = () => {
    setSpecText('')
    setFile(null)
    setError(null)
    setMode('paste')
  }

  const submit = async (e) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)
    try {
      if (mode === 'file') {
        if (!file) throw new Error('choose a .yaml/.yml/.json file first')
        const data = new FormData()
        data.append('file', file)
        await api.post(`/services/${serviceId}/specs/`, data)
      } else {
        if (!specText.trim()) throw new Error('paste the OpenAPI text first')
        await api.post(`/services/${serviceId}/specs/`, { spec_text: specText })
      }
      reset()
      onClose()
      onUploaded()
    } catch (err) {
      setError(errorMessage(err, 'Upload rejected — check the spec'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="md">
      <form onSubmit={submit}>
        <DialogTitle>Upload a spec version</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}
            <Tabs value={mode} onChange={(_, v) => setMode(v)}>
              <Tab value="paste" label="Paste text" />
              <Tab value="file" label="Upload file" />
            </Tabs>

            {mode === 'paste' ? (
              <TextField
                label="OpenAPI 3.0 YAML or JSON"
                placeholder="openapi: 3.0.3 ..."
                multiline
                rows={16}
                value={specText}
                onChange={(e) => setSpecText(e.target.value)}
                fullWidth
                slotProps={{ input: { sx: { fontFamily: 'monospace', fontSize: 13 } } }}
              />
            ) : (
              <Stack spacing={1}>
                <Button variant="outlined" component="label" startIcon={<UploadFileIcon />}>
                  {file ? file.name : 'Choose .yaml / .yml / .json file'}
                  <input
                    type="file"
                    hidden
                    accept=".yaml,.yml,.json,text/yaml,application/json"
                    onChange={(e) => setFile(e.target.files?.[0] ?? null)}
                  />
                </Button>
                <Typography variant="caption" color="text.secondary">
                  The file wins if both are provided; max 2 MB, OpenAPI 3.0.x with `info.version`.
                </Typography>
              </Stack>
            )}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button type="submit" variant="contained" disabled={submitting}>
            {submitting ? 'Uploading…' : 'Upload'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

function CompareDialog({ open, onClose, specs, onCompared }) {
  const [baseId, setBaseId] = useState('')
  const [targetId, setTargetId] = useState('')
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  const submit = async (e) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)
    try {
      const { data } = await api.post('/comparisons/', {
        base_spec_id: Number(baseId),
        target_spec_id: Number(targetId),
      })
      onClose()
      onCompared(data)
    } catch (err) {
      setError(errorMessage(err, 'Comparison failed'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <form onSubmit={submit}>
        <DialogTitle>Compare two versions</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}
            <TextField
              select
              label="Base version (old)"
              value={baseId}
              onChange={(e) => setBaseId(e.target.value)}
              required
            >
              {specs.map((s) => (
                <MenuItem key={s.id} value={s.id}>
                  v{s.version} (#{s.id})
                </MenuItem>
              ))}
            </TextField>
            <TextField
              select
              label="Target version (new)"
              value={targetId}
              onChange={(e) => setTargetId(e.target.value)}
              required
            >
              {specs.map((s) => (
                <MenuItem key={s.id} value={s.id}>
                  v{s.version} (#{s.id})
                </MenuItem>
              ))}
            </TextField>
            <Typography variant="caption" color="text.secondary">
              Both versions must belong to this service.
            </Typography>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button type="submit" variant="contained" disabled={submitting || !baseId || !targetId}>
            {submitting ? 'Comparing…' : 'Compare'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

function SpecViewDialog({ serviceId, specId, onClose }) {
  const [spec, setSpec] = useState(null)
  const [tab, setTab] = useState('spec')
  const [error, setError] = useState(null)

  useEffect(() => {
    if (!specId) return
    setSpec(null)
    setTab('spec')
    api
      .get(`/services/${serviceId}/specs/${specId}/`)
      .then((res) => setSpec(res.data))
      .catch((err) => setError(errorMessage(err)))
  }, [serviceId, specId])

  return (
    <Dialog open={Boolean(specId)} onClose={onClose} fullWidth maxWidth="lg">
      <DialogTitle>
        Spec #{specId} {spec ? `— v${spec.version}` : ''}
      </DialogTitle>
      <DialogContent>
        {error && <Alert severity="error">{error}</Alert>}
        {spec && (
          <>
            <Tabs value={tab} onChange={(_, v) => setTab(v)} sx={{ mb: 1 }}>
              <Tab value="spec" label="Raw spec" />
              <Tab value="contract" label="Resolved contract" />
            </Tabs>
            <TextField
              multiline
              fullWidth
              rows={22}
              value={
                tab === 'spec' ? spec.spec : JSON.stringify(spec.contract ?? {}, null, 2)
              }
              slotProps={{ input: { readOnly: true, sx: { fontFamily: 'monospace', fontSize: 12 } } }}
            />
          </>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  )
}

export function PublishResultDialog({ result, onClose }) {
  if (!result) return null
  const failed = Boolean(result._error)
  return (
    <Dialog open onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>Publishing attempt — {failed ? 'failed' : result.status}</DialogTitle>
      <DialogContent>
        {failed ? (
          <Alert severity="error">{result._error}</Alert>
        ) : (
          <Stack spacing={2}>
            <Stack direction="row" spacing={1}>
              <SeverityChip value={result.status} />
              <Chip size="small" label={`v${result.version} · ${result.service_name}`} />
            </Stack>
            {result.affected_consumers?.length > 0 && (
              <Stack>
                <Typography variant="subtitle2">Affected consumers</Typography>
                <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                  {result.affected_consumers.map((name) => (
                    <Chip key={name} size="small" color="error" variant="outlined" label={name} />
                  ))}
                </Stack>
              </Stack>
            )}
            {result.blocked_reasons?.length > 0 && (
              <Stack>
                <Typography variant="subtitle2">Reasons</Typography>
                {result.blocked_reasons.map((r, i) => (
                  <Typography key={i} variant="body2" color="text.secondary">
                    • {r}
                  </Typography>
                ))}
              </Stack>
            )}
            {result.status === 'approved' && (
              <Alert severity="success">The version is now this service's published one.</Alert>
            )}
            {result.status === 'blocked' && (
              <Alert severity="warning">
                The version stays unpublished. Review it under Publishing (approve or reject).
              </Alert>
            )}
          </Stack>
        )}
      </DialogContent>
      <DialogActions>
        {result.status === 'blocked' && (
          <Button component={RouterLink} to="/publishing" onClick={onClose}>
            Go to publishing
          </Button>
        )}
        <Button onClick={onClose} variant="contained">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  )
}

import { useCallback, useEffect, useState } from 'react'
import {
  Alert,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  LinearProgress,
  MenuItem,
  Stack,
  TextField,
  Typography,
} from '@mui/material'
import AddIcon from '@mui/icons-material/Add'
import DeleteIcon from '@mui/icons-material/Delete'
import RefreshIcon from '@mui/icons-material/Refresh'
import api from '../api/client'
import errorMessage from '../api/errorMessage'

const METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']

const EMPTY_USE = { provider: '', method: 'GET', path: '', sends: '', reads: '' }

export default function ConsumersPage() {
  const [consumers, setConsumers] = useState([])
  const [services, setServices] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [open, setOpen] = useState(false)

  const load = useCallback(() => {
    setLoading(true)
    Promise.all([api.get('/consumers/'), api.get('/services/')])
      .then(([cRes, sRes]) => {
        setConsumers(cRes.data.results ?? cRes.data)
        setServices(sRes.data.results ?? sRes.data)
        setError(null)
      })
      .catch((err) => setError(errorMessage(err)))
      .finally(() => setLoading(false))
  }, [])

  useEffect(load, [load])

  return (
    <Stack spacing={3}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="h4">Consumers</Typography>
        <Stack direction="row" spacing={1}>
          <IconButton onClick={load} title="Refresh">
            <RefreshIcon />
          </IconButton>
          <Button variant="contained" startIcon={<AddIcon />} onClick={() => setOpen(true)}>
            Register consumer
          </Button>
        </Stack>
      </Stack>

      {error && <Alert severity="error">{error}</Alert>}
      {loading && <LinearProgress />}
      {!loading && consumers.length === 0 && (
        <Typography color="text.secondary">
          No consumers registered yet. A consumer declares which provider endpoints it calls and
          which fields it sends/reads — that's what powers impact analysis.
        </Typography>
      )}

      <Grid container spacing={2}>
        {consumers.map((consumer) => (
          <Grid key={consumer.id} size={{ xs: 12, md: 6 }}>
            <Stack spacing={1} sx={{ p: 2, border: 1, borderColor: 'divider', borderRadius: 2 }}>
              <Stack direction="row" alignItems="center" justifyContent="space-between">
                <Typography variant="h6">{consumer.name}</Typography>
                <Chip size="small" variant="outlined" label={`team: ${consumer.team}`} />
              </Stack>
              <Divider />
              {consumer.uses.length === 0 && (
                <Typography variant="body2" color="text.secondary">
                  No declared uses.
                </Typography>
              )}
              {consumer.uses.map((use) => (
                <Stack key={use.id} spacing={0.5}>
                  <Stack direction="row" spacing={1} alignItems="center">
                    <Chip size="small" color="primary" label={use.method} sx={{ minWidth: 64 }} />
                    <Typography variant="body2" sx={{ fontFamily: 'monospace' }}>
                      {use.provider}
                      {use.path}
                    </Typography>
                  </Stack>
                  <Typography variant="caption" color="text.secondary">
                    sends: {use.sends.length ? use.sends.join(', ') : '—'} · reads:{' '}
                    {use.reads.length ? use.reads.join(', ') : '—'}
                  </Typography>
                </Stack>
              ))}
            </Stack>
          </Grid>
        ))}
      </Grid>

      <RegisterConsumerDialog open={open} onClose={() => setOpen(false)} services={services} onSaved={load} />
    </Stack>
  )
}

function RegisterConsumerDialog({ open, onClose, services, onSaved }) {
  const [name, setName] = useState('')
  const [team, setTeam] = useState('')
  const [uses, setUses] = useState([{ ...EMPTY_USE }])
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  const setUse = (index, field, value) =>
    setUses((list) => list.map((u, i) => (i === index ? { ...u, [field]: value } : u)))

  const submit = async (e) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)
    try {
      const payload = {
        consumer: name,
        team,
        uses: uses.map((u) => ({
          provider: u.provider,
          method: u.method,
          path: u.path,
          sends: u.sends.split(',').map((s) => s.trim()).filter(Boolean),
          reads: u.reads.split(',').map((s) => s.trim()).filter(Boolean),
        })),
      }
      await api.post('/consumers/', payload)
      setName('')
      setTeam('')
      setUses([{ ...EMPTY_USE }])
      onClose()
      onSaved()
    } catch (err) {
      setError(errorMessage(err, 'Registration failed'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="md">
      <form onSubmit={submit}>
        <DialogTitle>Register a consumer</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}
            <Stack direction="row" spacing={2}>
              <TextField
                label="Consumer name"
                placeholder="mobile-app"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                fullWidth
              />
              <TextField
                label="Team"
                placeholder="Mobile"
                value={team}
                onChange={(e) => setTeam(e.target.value)}
                required
                fullWidth
              />
            </Stack>

            <Typography variant="subtitle2">Declared uses</Typography>
            {uses.map((use, index) => (
              <Stack key={index} spacing={1.5} sx={{ p: 1.5, border: 1, borderColor: 'divider', borderRadius: 1 }}>
                <Stack direction="row" spacing={1.5} alignItems="center">
                  <TextField
                    select
                    label="Provider"
                    value={use.provider}
                    onChange={(e) => setUse(index, 'provider', e.target.value)}
                    sx={{ minWidth: 160 }}
                    required
                  >
                    {services.map((s) => (
                      <MenuItem key={s.id} value={s.name}>
                        {s.name}
                      </MenuItem>
                    ))}
                  </TextField>
                  <TextField
                    select
                    label="Method"
                    value={use.method}
                    onChange={(e) => setUse(index, 'method', e.target.value)}
                    sx={{ minWidth: 110 }}
                  >
                    {METHODS.map((m) => (
                      <MenuItem key={m} value={m}>
                        {m}
                      </MenuItem>
                    ))}
                  </TextField>
                  <TextField
                    label="Path"
                    placeholder="/quotes/{id}"
                    value={use.path}
                    onChange={(e) => setUse(index, 'path', e.target.value)}
                    required
                    fullWidth
                    slotProps={{ input: { sx: { fontFamily: 'monospace' } } }}
                  />
                  <IconButton
                    onClick={() => setUses((list) => list.filter((_, i) => i !== index))}
                    disabled={uses.length === 1}
                    title="Remove use"
                  >
                    <DeleteIcon />
                  </IconButton>
                </Stack>
                <Stack direction="row" spacing={1.5}>
                  <TextField
                    label="Sends (comma separated)"
                    placeholder="vehicle.make, rider.age"
                    value={use.sends}
                    onChange={(e) => setUse(index, 'sends', e.target.value)}
                    fullWidth
                  />
                  <TextField
                    label="Reads (comma separated)"
                    placeholder="premium.total, status"
                    value={use.reads}
                    onChange={(e) => setUse(index, 'reads', e.target.value)}
                    fullWidth
                  />
                </Stack>
              </Stack>
            ))}
            <Button
              startIcon={<AddIcon />}
              onClick={() => setUses((list) => [...list, { ...EMPTY_USE }])}
              sx={{ alignSelf: 'flex-start' }}
            >
              Add use
            </Button>
            <Typography variant="caption" color="text.secondary">
              Field paths use dots for nesting and [] for array items, e.g. premium.breakdown[].amount.
              Re-registering an existing consumer name replaces its uses.
            </Typography>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button type="submit" variant="contained" disabled={submitting}>
            {submitting ? 'Registering…' : 'Register'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

import { useCallback, useEffect, useState } from 'react'
import {
  Alert,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material'
import RefreshIcon from '@mui/icons-material/Refresh'
import CheckIcon from '@mui/icons-material/Check'
import CloseIcon from '@mui/icons-material/Close'
import api from '../api/client'
import errorMessage from '../api/errorMessage'
import SeverityChip from '../components/SeverityChip'

export default function PublishingPage() {
  const [attempts, setAttempts] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [decision, setDecision] = useState(null) // {attempt, action}
  const [banner, setBanner] = useState(null)

  const load = useCallback(() => {
    setLoading(true)
    api
      .get('/publishing-attempts/')
      .then((res) => setAttempts(res.data.results ?? res.data))
      .catch((err) => setError(errorMessage(err)))
      .finally(() => setLoading(false))
  }, [])

  useEffect(load, [load])

  const decided = (message) => {
    setDecision(null)
    setBanner({ severity: 'success', message })
    load()
  }

  return (
    <Stack spacing={3}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="h4">Publishing</Typography>
        <IconButton onClick={load} title="Refresh">
          <RefreshIcon />
        </IconButton>
      </Stack>

      {banner && (
        <Alert severity={banner.severity} onClose={() => setBanner(null)}>
          {banner.message}
        </Alert>
      )}
      {error && <Alert severity="error">{error}</Alert>}
      {loading && <LinearProgress />}
      {!loading && attempts.length === 0 && (
        <Typography color="text.secondary">
          No publishing attempts yet — open a service and press “Publish” on one of its versions.
        </Typography>
      )}

      {attempts.length > 0 && (
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Attempt</TableCell>
                <TableCell>Version</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Reasons / outcome</TableCell>
                <TableCell>Decision</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {attempts.map((attempt) => (
                <TableRow key={attempt.id} hover>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>
                      #{attempt.id} · {attempt.service_name}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {new Date(attempt.created_at).toLocaleString()}
                    </Typography>
                  </TableCell>
                  <TableCell>v{attempt.version}</TableCell>
                  <TableCell>
                    <SeverityChip value={attempt.status} />
                  </TableCell>
                  <TableCell sx={{ maxWidth: 380 }}>
                    {attempt.status === 'approved' && !attempt.comment && (
                      <Typography variant="body2" color="text.secondary">
                        No affected consumers — auto-approved.
                      </Typography>
                    )}
                    {attempt.blocked_reasons?.map((reason, i) => (
                      <Typography key={i} variant="body2" color="text.secondary">
                        • {reason}
                      </Typography>
                    ))}
                    {attempt.affected_consumers?.length > 0 && (
                      <Stack direction="row" spacing={0.5} sx={{ mt: 0.5 }} flexWrap="wrap" useFlexGap>
                        {attempt.affected_consumers.map((name) => (
                          <Chip key={name} size="small" color="error" variant="outlined" label={name} />
                        ))}
                      </Stack>
                    )}
                    {attempt.comment && (
                      <Typography variant="caption" sx={{ display: 'block', mt: 0.5 }}>
                        “{attempt.comment}”
                      </Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    {attempt.decided_by ? (
                      <>
                        <Typography variant="body2">{attempt.decided_by}</Typography>
                        <Typography variant="caption" color="text.secondary">
                          {attempt.decided_at ? new Date(attempt.decided_at).toLocaleString() : ''}
                        </Typography>
                      </>
                    ) : (
                      '—'
                    )}
                  </TableCell>
                  <TableCell align="right">
                    {attempt.status === 'blocked' ? (
                      <Stack direction="row" spacing={1} justifyContent="flex-end">
                        <Button
                          size="small"
                          color="success"
                          startIcon={<CheckIcon />}
                          onClick={() => setDecision({ attempt, action: 'approve' })}
                        >
                          Approve
                        </Button>
                        <Button
                          size="small"
                          color="error"
                          startIcon={<CloseIcon />}
                          onClick={() => setDecision({ attempt, action: 'reject' })}
                        >
                          Reject
                        </Button>
                      </Stack>
                    ) : (
                      <Typography variant="caption" color="text.secondary">
                        decided
                      </Typography>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <DecisionDialog
        decision={decision}
        onClose={() => setDecision(null)}
        onDone={decided}
      />
    </Stack>
  )
}

function DecisionDialog({ decision, onClose, onDone }) {
  const [comment, setComment] = useState('')
  const [error, setError] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    setComment('')
    setError(null)
  }, [decision])

  if (!decision) return null
  const { attempt, action } = decision
  const isApprove = action === 'approve'

  const submit = async (e) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)
    try {
      await api.post(`/publishing-attempts/${attempt.id}/${action}/`, { comment })
      onDone(
        isApprove
          ? `Attempt #${attempt.id} approved — v${attempt.version} is now published.`
          : `Attempt #${attempt.id} rejected — v${attempt.version} stays unpublished.`,
      )
    } catch (err) {
      setError(errorMessage(err, 'Decision failed'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open onClose={onClose} fullWidth maxWidth="sm">
      <form onSubmit={submit}>
        <DialogTitle>
          {isApprove ? 'Approve' : 'Reject'} attempt #{attempt.id} (v{attempt.version} of{' '}
          {attempt.service_name})
        </DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            {error && <Alert severity="error">{error}</Alert>}
            {isApprove && (
              <Alert severity="warning">
                Approving publishes this version even though {attempt.affected_consumers.length} consumer(s)
                are affected.
              </Alert>
            )}
            <TextField
              label="Reviewer comment"
              placeholder="Reviewed with the mobile team — coordinated release"
              multiline
              rows={3}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              autoFocus
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancel</Button>
          <Button type="submit" variant="contained" color={isApprove ? 'success' : 'error'} disabled={submitting}>
            {submitting ? 'Saving…' : isApprove ? 'Approve & publish' : 'Reject'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

import { useCallback, useEffect, useState } from 'react'
import {
  Alert,
  Box,
  Button,
  Chip,
  IconButton,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material'
import RefreshIcon from '@mui/icons-material/Refresh'
import DeleteIcon from '@mui/icons-material/Delete'
import api from '../api/client'
import errorMessage from '../api/errorMessage'

const EVENT_COLORS = {
  'publish.approved': 'success',
  'publish.blocked': 'error',
  'publish.rejected': 'warning',
}

export default function NotificationsPage() {
  const [events, setEvents] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  const load = useCallback(() => {
    setLoading(true)
    api
      .get('/webhook-events/')
      .then((res) => setEvents(res.data.results ?? res.data))
      .catch((err) => setError(errorMessage(err)))
      .finally(() => setLoading(false))
  }, [])

  useEffect(load, [load])

  const clear = async () => {
    await api.delete('/webhook-events/')
    load()
  }

  return (
    <Stack spacing={3}>
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="h4">Notifications</Typography>
        <Stack direction="row" spacing={1}>
          <IconButton onClick={load} title="Refresh">
            <RefreshIcon />
          </IconButton>
          <Button startIcon={<DeleteIcon />} color="error" onClick={clear} disabled={events.length === 0}>
            Clear
          </Button>
        </Stack>
      </Stack>

      <Typography variant="body2" color="text.secondary">
        Every publishing decision is POSTed to the built-in receiver
        (<code>/api/webhook-events/receive/</code>) — this is what an external webhook consumer
        would receive.
      </Typography>

      {error && <Alert severity="error">{error}</Alert>}
      {loading && <LinearProgress />}
      {!loading && events.length === 0 && (
        <Typography color="text.secondary">No notifications received yet.</Typography>
      )}

      <Stack spacing={1.5}>
        {events.map((event) => (
          <Box key={event.id} sx={{ p: 1.5, border: 1, borderColor: 'divider', borderRadius: 1 }}>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
              <Chip
                size="small"
                color={EVENT_COLORS[event.body?.event] || 'default'}
                label={event.body?.event || 'unknown'}
              />
              {event.body?.service && (
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  {event.body.service} v{event.body.version}
                </Typography>
              )}
              {event.body?.affected_consumers?.length > 0 && (
                <Stack direction="row" spacing={0.5} flexWrap="wrap" useFlexGap>
                  {event.body.affected_consumers.map((name) => (
                    <Chip key={name} size="small" color="error" variant="outlined" label={name} />
                  ))}
                </Stack>
              )}
              <Box sx={{ flexGrow: 1 }} />
              <Typography variant="caption" color="text.secondary">
                #{event.id} · {new Date(event.received_at).toLocaleString()}
              </Typography>
            </Stack>
            {event.body?.blocked_reasons?.length > 0 && (
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                {event.body.blocked_reasons.join(' · ')}
              </Typography>
            )}
            <Box
              component="pre"
              sx={{
                mt: 1,
                mb: 0,
                fontSize: 11,
                fontFamily: 'monospace',
                overflow: 'auto',
                color: 'text.secondary',
              }}
            >
              {JSON.stringify(event.body, null, 2)}
            </Box>
          </Box>
        ))}
      </Stack>
    </Stack>
  )
}

