const { readFileSync, writeFileSync } = require('fs')
const files = [
  'components/Layout.jsx', 'App.jsx', 'pages/ConsumersPage.jsx',
  'pages/ComparisonDetailPage.jsx', 'pages/DashboardPage.jsx', 'pages/ComparisonsPage.jsx',
  'pages/PublishingPage.jsx', 'pages/ServicesPage.jsx', 'pages/NotificationsPage.jsx',
  'pages/ServiceDetailPage.jsx',
]
// move deprecated system props into sx, merging with an existing sx if present
for (const f of files) {
  let src = readFileSync(f, 'utf8')
  // patterns: alignItems="..."  justifyContent="..."  flexWrap="wrap"  useFlexGap
  src = src.replace(/<Stack([^>]*?)\/>/gs, (m) => m) // placeholder, handled below
  const lineFix = (line) => {
    if (!line.includes('Stack') || (!line.includes('alignItems=') && !line.includes('justifyContent=') && !line.includes('flexWrap=') && !line.includes('useFlexGap'))) return line
    let moved = []
    let out = line
    for (const prop of ['alignItems', 'justifyContent', 'flexWrap']) {
      const re = new RegExp(`\\s${prop}="([^"]+)"`)
      if (re.test(out)) {
        moved.push(`${prop}: '${out.match(re)[1]}'`)
        out = out.replace(re, '')
      }
    }
    out = out.replace(/\suseFlexGap/g, '')
    if (moved.length === 0) return line
    if (out.includes('sx={{')) {
      // merge into existing sx={{ ... }}
      out = out.replace(/sx=\{\{\s*/, `sx={{ ${moved.join(', ')}, `)
    } else {
      out = out.replace(/(\s*)$/, '') // trim trailing
      out = out.replace(/>(?:\s*)$/, '') // no, we're inside an open tag on one line
      // insert before the closing bracket of the tag: lines like <Stack ... >
      out = out.replace(/\s*(\/?)>\s*$/, (mm, slash) => ` sx={{ ${moved.join(', ')} }}${slash}>`)
    }
    return out
  }
  const fixed = src.split('\n').map(lineFix).join('\n')
  writeFileSync(f, fixed)
  console.log('fixed', f)
}
EOF
