const tabID = 'tab_1132ffaf-2f16-4d48-8cff-e5141b347188'
// options render in a portal listbox; interact via DOM directly
const r = await tools.browser.evaluate({
  tabID,
  script: `(() => {
    const listbox = document.querySelector('ul[role=listbox]')
    if (!listbox) return { ok: false }
    const options = [...listbox.querySelectorAll('[role=option]')]
    // base = the v2.0.0 option (text contains 'v2.0.0')
    const base = options.find(o => o.innerText.includes('v2.0.0'))
    base?.click()
    return { ok: Boolean(base), total: options.length, texts: options.map(o => o.innerText) }
  })()`,
})
return r.value

