# Contract Guard frontend server.
# Serves the built SPA and proxies the API + Swagger to the backend
# over the compose network (service name: backend).

server {
    listen 80;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # SPA: every route falls back to index.html (react-router)
    location / {
        try_files $uri $uri/ /index.html;
    }

    # API -> Django. 4m allows the 2 MB spec upload with multipart overhead.
    location /api/ {
        proxy_pass http://backend:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        client_max_body_size 4m;
    }

    # Swagger UI through the same origin as the app
    location /docs/ {
        proxy_pass http://backend:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
